/**
 * Subset of the types generated by Supabase for the columns the app reads.
 * Replace with full CLI output once `supabase gen types` runs in CI.
 */
export type OrgKind = "buyer" | "seller";
export type EntityType =
  "individual" | "proprietorship" | "partnership" | "trust_society" | "llp" | "company";
export type OrgStatus =
  "draft" | "pending_payment" | "pending_review" | "active" | "suspended" | "rejected";
export type UserRole = "org_user" | "admin";

export type ProductStatus =
  "draft" | "pending" | "notify" | "published" | "unpublished" | "rejected";

export type SellerProduct = {
  id: string;
  display_no: string;
  title: string;
  category_id: string;
  category_name: string;
  mrp_paise: number;
  discount_bps: number;
  net_paise: number;
  stock_qty: number;
  unit: string;
  status: ProductStatus;
  review_note: string | null;
  description: string | null;
  state_codes: string[];
  specs: Record<string, string>;
  images: { id: string; path: string }[];
};

export type PendingProduct = {
  id: string;
  display_no: string;
  title: string;
  description: string | null;
  category_name: string;
  seller_name: string;
  mrp_paise: number;
  discount_bps: number;
  net_paise: number;
  stock_qty: number;
  unit: string;
};

export type AdminCategory = {
  id: string;
  parent_id: string | null;
  name: string;
  slug: string;
  description: string | null;
  is_active: boolean;
  sort_order: number;
};

export type PublicProduct = {
  id: string;
  display_no: string;
  category_slug: string;
  category_name: string;
  title: string;
  mrp_paise: number;
  discount_bps: number;
  net_paise: number;
  unit: string;
  city: string | null;
  state_code: string | null;
  image_path: string | null;
};

export type PublicProductDetail = PublicProduct & {
  description: string | null;
  stock_qty: number;
  delivery_states: string[];
  specs: { label: string; value: string; unit: string | null }[];
  image_paths: string[];
};

type Table<Row> = {
  Row: Row;
  Insert: never;
  Update: never;
  Relationships: [];
};

export type Database = {
  public: {
    Tables: {
      categories: Table<{
        id: string;
        name: string;
        slug: string;
        parent_id: string | null;
        description: string | null;
        sort_order: number;
      }>;
      spec_definitions: Table<{
        id: string;
        category_id: string;
        label: string;
        kind: "text" | "number" | "enum";
        unit: string | null;
        is_required: boolean;
      }>;
      organisations: Table<{
        id: string;
        kind: OrgKind;
        legal_name: string;
        status: OrgStatus;
        pan_last4: string | null;
        gstin: string | null;
      }>;
      org_addresses: Table<{ id: string; city: string; pincode: string }>;
      bank_accounts: Table<{ id: string; account_last4: string; ifsc: string }>;
      turnover_declarations: Table<{ financial_year: string }>;
      profiles: Table<{
        user_id: string;
        org_id: string | null;
        role: UserRole;
        email: string | null;
      }>;
    };
    Views: Record<never, never>;
    Functions: {
      api_begin: {
        Args: { p_key: string; p_route: string; p_hash: string };
        Returns: { status: number; body: unknown } | null;
      };
      api_finish: {
        Args: { p_key: string; p_status: number; p_body: unknown };
        Returns: undefined;
      };
      health_check: { Args: Record<never, never>; Returns: boolean };
      current_org_id: { Args: Record<never, never>; Returns: string };
      add_product_image: { Args: { p_id: string; p_path: string }; Returns: string };
      remove_product_image: { Args: { p_media_id: string }; Returns: string };
      delete_product: { Args: { p_id: string }; Returns: string[] };
      category_spec_values: {
        Args: { p_category_slug: string };
        Returns: { spec_id: string; label: string; value: string }[];
      };
      request_category: { Args: { p_name: string; p_details: string }; Returns: string };
      admin_pending_category_requests: {
        Args: Record<never, never>;
        Returns: { id: string; name: string; details: string; seller_name: string }[];
      };
      admin_review_category_request: {
        Args: { p_id: string; p_approve: boolean; p_note: string };
        Returns: undefined;
      };
      admin_categories: { Args: Record<never, never>; Returns: AdminCategory[] };
      admin_save_category: {
        Args: {
          p_id: string | null;
          p_parent_id: string | null;
          p_name: string;
          p_slug: string;
          p_description: string;
          p_is_active: boolean;
          p_sort_order: number;
        };
        Returns: string;
      };
      admin_add_spec: {
        Args: {
          p_category_id: string;
          p_label: string;
          p_kind: "text" | "number" | "enum";
          p_unit: string;
          p_is_key: boolean;
          p_is_required: boolean;
        };
        Returns: string;
      };
      save_product: {
        Args: {
          p_id: string | null;
          p_category_id: string;
          p_title: string;
          p_description: string;
          p_mrp_paise: number;
          p_discount_bps: number;
          p_stock_qty: number;
          p_unit: string;
          p_state_codes: string[];
          p_specs: { specId: string; value: string }[];
        };
        Returns: string;
      };
      submit_product: { Args: { p_id: string }; Returns: undefined };
      set_product_visibility: { Args: { p_id: string; p_visible: boolean }; Returns: undefined };
      update_product_commercials: {
        Args: { p_id: string; p_mrp_paise: number; p_discount_bps: number; p_stock_qty: number };
        Returns: undefined;
      };
      seller_products: { Args: Record<never, never>; Returns: SellerProduct[] };
      admin_pending_products: { Args: Record<never, never>; Returns: PendingProduct[] };
      admin_review_product: {
        Args: { p_id: string; p_decision: string; p_note: string };
        Returns: undefined;
      };
      admin_payment_pending_sellers: {
        Args: Record<never, never>;
        Returns: { id: string; legal_name: string; gstin: string | null }[];
      };
      admin_test_activate_seller: {
        Args: { p_org_id: string; p_reason: string };
        Returns: undefined;
      };
      search_products: {
        Args: {
          p_query?: string;
          p_category_slug?: string;
          p_state_code?: string;
          p_sort?: string;
          p_limit?: number;
          p_offset?: number;
          p_spec_id?: string;
          p_spec_value?: string;
        };
        Returns: PublicProduct[];
      };
      public_product: {
        Args: { p_id: string };
        Returns: PublicProductDetail[];
      };
      create_organisation: {
        Args: {
          p_kind: OrgKind;
          p_entity_type: EntityType;
          p_legal_name: string;
          p_policy_version: string;
        };
        Returns: string;
      };
      save_business_identity: {
        Args: { p_pan: string; p_gstin: string; p_incorporated_on?: string };
        Returns: undefined;
      };
      add_registered_address: {
        Args: {
          p_line1: string;
          p_line2: string;
          p_city: string;
          p_state_code: string;
          p_pincode: string;
        };
        Returns: string;
      };
      add_bank_account: {
        Args: { p_holder_name: string; p_account_no: string; p_ifsc: string };
        Returns: string;
      };
      save_turnover: {
        Args: { p_years: { financialYear: string; amountPaise: number }[] };
        Returns: undefined;
      };
      submit_organisation: { Args: Record<never, never>; Returns: OrgStatus };
      admin_pending_organisations: {
        Args: Record<never, never>;
        Returns: {
          id: string;
          kind: OrgKind;
          entity_type: EntityType;
          legal_name: string;
          pan_last4: string | null;
          gstin: string | null;
          created_at: string;
        }[];
      };
      admin_review_organisation: {
        Args: { p_org_id: string; p_approve: boolean; p_reason: string };
        Returns: undefined;
      };
    };
    Enums: Record<never, never>;
    CompositeTypes: Record<never, never>;
  };
};
